-- Phase 34 extends existing tracking_sessions, persisted telemetry, Route Intelligence,
-- Phase 22, Customer Portal and device authorities. It does not create another telemetry stream.
CREATE OR REPLACE FUNCTION public.tracking34_internal_read(c UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_company_member(c) AND public.has_any_role(c,ARRAY['admin','fleet_controller','dispatcher','operations_manager','fleet_manager','customer_care','supervisor','executive','managing_director','viewer','support_engineer']::public.app_role[]) AND NOT EXISTS(SELECT 1 FROM public.customer_portal_memberships m WHERE m.company_id=c AND m.user_id=auth.uid() AND m.status='active') $$;
CREATE OR REPLACE FUNCTION public.tracking34_internal_write(c UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.tracking34_internal_read(c) AND public.has_any_role(c,ARRAY['admin','fleet_controller','dispatcher','operations_manager','fleet_manager','customer_care','supervisor']::public.app_role[]) $$;

CREATE TABLE public.tracking_vehicle_states(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE,tracking_session_id UUID REFERENCES public.tracking_sessions(id) ON DELETE SET NULL,source_state TEXT,derived_state TEXT NOT NULL CHECK(derived_state IN('moving','idle','stationary','loading','unloading','at_customer','at_depot','at_warehouse','at_fuel_stop','at_border','at_port','breakdown','incident','sos','offline','stale','unknown','no_device','device_fault')),device_timestamp TIMESTAMPTZ,received_at TIMESTAMPTZ,freshness_state TEXT NOT NULL CHECK(freshness_state IN('live','recent','stale','offline','unknown')),source TEXT NOT NULL,quality_score NUMERIC CHECK(quality_score BETWEEN 0 AND 100),confidence TEXT NOT NULL CHECK(confidence IN('high','medium','low','unavailable')),evidence_references JSONB NOT NULL DEFAULT '[]',calculated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(confidence='unavailable' OR jsonb_array_length(evidence_references)>0),UNIQUE(company_id,vehicle_id,calculated_at));
CREATE TABLE public.tracking_trip_progress(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tracking_session_id UUID NOT NULL REFERENCES public.tracking_sessions(id) ON DELETE CASCADE,planned_distance_km NUMERIC,completed_distance_km NUMERIC,remaining_distance_km NUMERIC,completed_stops INTEGER NOT NULL DEFAULT 0,remaining_stops INTEGER NOT NULL DEFAULT 0,current_segment TEXT,current_stop_id UUID,next_stop_id UUID,dwell_seconds INTEGER,delay_seconds INTEGER,source_references JSONB NOT NULL DEFAULT '[]',calculated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(completed_stops>=0 AND remaining_stops>=0));
CREATE TABLE public.tracking_eta_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tracking_session_id UUID NOT NULL REFERENCES public.tracking_sessions(id) ON DELETE CASCADE,eta TIMESTAMPTZ,confidence TEXT NOT NULL CHECK(confidence IN('high','medium','low','unavailable')),confidence_band_minutes INTEGER,contributing_factors JSONB NOT NULL DEFAULT '[]',missing_inputs JSONB NOT NULL DEFAULT '[]',freshness_state TEXT NOT NULL,source_period JSONB NOT NULL DEFAULT '{}',assumptions JSONB NOT NULL DEFAULT '[]',evidence_references JSONB NOT NULL DEFAULT '[]',calculated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(confidence='unavailable' OR (eta IS NOT NULL AND jsonb_array_length(evidence_references)>0)));
CREATE TABLE public.tracking_route_deviations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tracking_session_id UUID NOT NULL REFERENCES public.tracking_sessions(id) ON DELETE CASCADE,deviation_type TEXT NOT NULL CHECK(deviation_type IN('off_route','unplanned_divergence','missed_stop','incorrect_sequence','return_to_route','prolonged_deviation','geofence_mismatch')),distance_meters NUMERIC,duration_seconds INTEGER NOT NULL DEFAULT 0,first_detected_at TIMESTAMPTZ NOT NULL,current_state TEXT NOT NULL CHECK(current_state IN('detected','reviewing','recovered','resolved')),confidence TEXT NOT NULL CHECK(confidence IN('high','medium','low','unavailable')),possible_explanations JSONB NOT NULL DEFAULT '[]',evidence_references JSONB NOT NULL DEFAULT '[]',recommended_human_review BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(confidence='unavailable' OR jsonb_array_length(evidence_references)>0));
CREATE TABLE public.tracking_geofences(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,name TEXT NOT NULL,geofence_type TEXT NOT NULL CHECK(geofence_type IN('depot','warehouse','customer','port','border','fuel_station','rest_stop','workshop','mine','construction_site','restricted_area','custom_area')),shape_type TEXT NOT NULL CHECK(shape_type IN('circle','polygon')),center_latitude DOUBLE PRECISION,center_longitude DOUBLE PRECISION,radius_meters NUMERIC,polygon_geojson JSONB,active BOOLEAN NOT NULL DEFAULT true,customer_safe BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((shape_type='circle' AND center_latitude BETWEEN -90 AND 90 AND center_longitude BETWEEN -180 AND 180 AND radius_meters>0) OR (shape_type='polygon' AND polygon_geojson IS NOT NULL)),UNIQUE(company_id,name));
CREATE TABLE public.tracking_geofence_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,geofence_id UUID NOT NULL REFERENCES public.tracking_geofences(id) ON DELETE CASCADE,vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE,tracking_session_id UUID REFERENCES public.tracking_sessions(id) ON DELETE SET NULL,event_type TEXT NOT NULL CHECK(event_type IN('entered','exited','dwell_started','dwell_exceeded','missed_arrival','unexpected_entry','recovered')),occurred_at TIMESTAMPTZ NOT NULL,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,confidence TEXT NOT NULL CHECK(confidence IN('high','medium','low','unavailable')),evidence_references JSONB NOT NULL DEFAULT '[]',customer_safe BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(confidence='unavailable' OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180 AND jsonb_array_length(evidence_references)>0)));
CREATE TABLE public.tracking_replay_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tracking_session_id UUID NOT NULL REFERENCES public.tracking_sessions(id) ON DELETE CASCADE,range_start TIMESTAMPTZ NOT NULL,range_end TIMESTAMPTZ NOT NULL,telemetry_point_count INTEGER NOT NULL DEFAULT 0,gap_count INTEGER NOT NULL DEFAULT 0,opened_by UUID NOT NULL DEFAULT auth.uid(),opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(range_end>=range_start AND telemetry_point_count>=0 AND gap_count>=0));
CREATE TABLE public.tracking_alerts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,vehicle_id UUID REFERENCES public.vehicles(id) ON DELETE SET NULL,tracking_session_id UUID REFERENCES public.tracking_sessions(id) ON DELETE SET NULL,alert_type TEXT NOT NULL CHECK(alert_type IN('sos','breakdown','severe_delay','prolonged_deviation','missed_arrival','offline','stale','device_fault','low_eta_confidence','geofence_breach','customer_follow_up')),priority TEXT NOT NULL CHECK(priority IN('normal','high','critical')),status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','acknowledged','investigating','resolved','false_positive')),owner_id UUID REFERENCES auth.users(id),source_evidence JSONB NOT NULL DEFAULT '[]',resolution_note TEXT,customer_impact BOOLEAN NOT NULL DEFAULT false,escalation_state TEXT NOT NULL DEFAULT 'none',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE public.tracking_alert_acknowledgements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,alert_id UUID NOT NULL REFERENCES public.tracking_alerts(id) ON DELETE CASCADE,acknowledged_by UUID NOT NULL DEFAULT auth.uid(),acknowledged_at TIMESTAMPTZ NOT NULL DEFAULT now(),note TEXT,UNIQUE(alert_id,acknowledged_by));
CREATE TABLE public.tracking_customer_visibility_policies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,customer_id UUID NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,shipment_id UUID,vehicle_id UUID REFERENCES public.vehicles(id) ON DELETE CASCADE,visibility_mode TEXT NOT NULL CHECK(visibility_mode IN('hidden','milestone_only','approximate_area','exact_location','delayed_location','delivery_window_only')),delay_minutes INTEGER NOT NULL DEFAULT 0 CHECK(delay_minutes>=0),cargo_sensitivity TEXT,policy_source TEXT NOT NULL,approved_by UUID REFERENCES auth.users(id),effective_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(visibility_mode<>'delayed_location' OR delay_minutes>0),UNIQUE(company_id,customer_id,shipment_id));
CREATE TABLE public.tracking_hourly_checks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tracking_session_id UUID REFERENCES public.tracking_sessions(id) ON DELETE CASCADE,shipment_id UUID,vehicle_id UUID REFERENCES public.vehicles(id) ON DELETE SET NULL,checked_at TIMESTAMPTZ NOT NULL,checked_by UUID NOT NULL DEFAULT auth.uid(),status TEXT NOT NULL CHECK(status IN('current','follow_up','escalated','unavailable')),follow_up_due_at TIMESTAMPTZ,acknowledged_at TIMESTAMPTZ,owner_id UUID REFERENCES auth.users(id),customer_safe_summary TEXT,internal_note TEXT,evidence_references JSONB NOT NULL DEFAULT '[]');
CREATE TABLE public.tracking_customer_updates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,customer_id UUID NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,shipment_id UUID,tracking_session_id UUID REFERENCES public.tracking_sessions(id) ON DELETE SET NULL,status TEXT NOT NULL,general_area TEXT,eta TIMESTAMPTZ,eta_confidence TEXT NOT NULL CHECK(eta_confidence IN('high','medium','low','unavailable')),delay_reason TEXT,next_milestone TEXT,pod_state TEXT,last_tracking_update TIMESTAMPTZ,prepared_by UUID NOT NULL DEFAULT auth.uid(),prepared_at TIMESTAMPTZ NOT NULL DEFAULT now(),communication_status TEXT NOT NULL DEFAULT 'prepared' CHECK(communication_status IN('prepared','queued','provider_confirmed','failed')),provider_confirmation_reference TEXT,CHECK(communication_status<>'provider_confirmed' OR provider_confirmation_reference IS NOT NULL));
CREATE TABLE public.tracking_map_provider_configs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,provider TEXT NOT NULL CHECK(provider IN('maplibre','mapbox','here','google_maps','tomtom','osm_compatible')),environment TEXT NOT NULL,capabilities JSONB NOT NULL DEFAULT '{}',style_reference TEXT,tile_reference TEXT,offline_regions_state TEXT NOT NULL DEFAULT 'not_configured' CHECK(offline_regions_state IN('configured','not_configured','unavailable')),active BOOLEAN NOT NULL DEFAULT false,changed_by UUID REFERENCES auth.users(id),changed_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,environment,provider));
CREATE TABLE public.tracking_map_match_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,telemetry_point_id UUID NOT NULL REFERENCES public.tracking_telemetry_points(id) ON DELETE CASCADE,raw_latitude DOUBLE PRECISION NOT NULL,raw_longitude DOUBLE PRECISION NOT NULL,matched_latitude DOUBLE PRECISION,matched_longitude DOUBLE PRECISION,road_confidence NUMERIC CHECK(road_confidence BETWEEN 0 AND 1),provider TEXT NOT NULL,provider_version TEXT,matched_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(raw_latitude BETWEEN -90 AND 90 AND raw_longitude BETWEEN -180 AND 180),UNIQUE(company_id,telemetry_point_id,provider,provider_version));
CREATE TABLE public.tracking_data_quality_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tracking_session_id UUID REFERENCES public.tracking_sessions(id) ON DELETE CASCADE,telemetry_point_id UUID REFERENCES public.tracking_telemetry_points(id) ON DELETE SET NULL,event_type TEXT NOT NULL CHECK(event_type IN('missing_gps','invalid_coordinates','duplicate_message','out_of_order','stale_timestamp','impossible_speed','teleportation','missing_heading','missing_ignition','missing_trip_link','map_match_failure','low_signal','low_battery')),severity TEXT NOT NULL CHECK(severity IN('informational','warning','critical')),quality_impact NUMERIC NOT NULL CHECK(quality_impact BETWEEN 0 AND 100),safe_metadata JSONB NOT NULL DEFAULT '{}',detected_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.tracking_operational_settings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL UNIQUE REFERENCES public.companies(id) ON DELETE CASCADE,live_seconds INTEGER NOT NULL DEFAULT 60,recent_seconds INTEGER NOT NULL DEFAULT 300,offline_seconds INTEGER NOT NULL DEFAULT 1800,default_map_view JSONB NOT NULL DEFAULT '{}',cluster_threshold INTEGER NOT NULL DEFAULT 50,customer_location_mode TEXT NOT NULL DEFAULT 'milestone_only',customer_delay_minutes INTEGER NOT NULL DEFAULT 15,route_deviation_meters INTEGER NOT NULL DEFAULT 250,deviation_duration_seconds INTEGER NOT NULL DEFAULT 300,dwell_threshold_seconds INTEGER NOT NULL DEFAULT 900,eta_refresh_seconds INTEGER NOT NULL DEFAULT 60,tracking_refresh_seconds INTEGER NOT NULL DEFAULT 30,wall_rotation_seconds INTEGER NOT NULL DEFAULT 60,customer_care_check_minutes INTEGER NOT NULL DEFAULT 60,working_hours JSONB NOT NULL DEFAULT '{}',timezone TEXT NOT NULL DEFAULT 'UTC',updated_by UUID REFERENCES auth.users(id),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(0<live_seconds AND live_seconds<recent_seconds AND recent_seconds<offline_seconds));
CREATE TABLE public.tracking_audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,event_type TEXT NOT NULL CHECK(event_type IN('vehicle_state_calculated','eta_calculated','route_deviation_detected','geofence_entered','geofence_exited','tracking_alert_created','tracking_alert_acknowledged','hourly_check_completed','customer_update_prepared','customer_visibility_changed','replay_opened','map_provider_changed','tracking_setting_changed')),entity_type TEXT NOT NULL,entity_id UUID NOT NULL,actor_id UUID DEFAULT auth.uid(),safe_metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION public.tracking34_customer_locations() RETURNS TABLE(vehicle_id UUID,visibility_mode TEXT,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,general_area TEXT,device_timestamp TIMESTAMPTZ,freshness_state TEXT) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.vehicle_id,p.visibility_mode,CASE WHEN p.visibility_mode='exact_location' OR (p.visibility_mode='delayed_location' AND l.device_timestamp<=now()-make_interval(mins=>p.delay_minutes)) THEN l.latitude WHEN p.visibility_mode='approximate_area' THEN round(l.latitude::numeric,2)::double precision END,CASE WHEN p.visibility_mode='exact_location' OR (p.visibility_mode='delayed_location' AND l.device_timestamp<=now()-make_interval(mins=>p.delay_minutes)) THEN l.longitude WHEN p.visibility_mode='approximate_area' THEN round(l.longitude::numeric,2)::double precision END,CASE WHEN p.visibility_mode IN('approximate_area','milestone_only','delayed_location') THEN 'Approximate operational area' END,l.device_timestamp,CASE WHEN l.device_timestamp>=now()-interval '60 seconds' THEN 'live' WHEN l.device_timestamp>=now()-interval '5 minutes' THEN 'recent' WHEN l.device_timestamp>=now()-interval '30 minutes' THEN 'stale' ELSE 'offline' END FROM public.tracking_customer_visibility_policies p JOIN public.customer_portal_memberships m ON m.company_id=p.company_id AND m.customer_id=p.customer_id AND m.user_id=auth.uid() AND m.status='active' LEFT JOIN public.vehicle_latest_locations l ON l.company_id=p.company_id AND l.vehicle_id=p.vehicle_id WHERE p.effective_at<=now() AND (p.expires_at IS NULL OR p.expires_at>now()) AND p.visibility_mode<>'hidden' $$;
GRANT EXECUTE ON FUNCTION public.tracking34_customer_locations() TO authenticated;

CREATE OR REPLACE FUNCTION public.tracking34_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Tracking evidence is append-only'; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['tracking_vehicle_states','tracking_eta_assessments','tracking_route_deviations','tracking_geofence_events','tracking_replay_sessions','tracking_alert_acknowledgements','tracking_map_match_records','tracking_data_quality_events','tracking_audit_logs'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.tracking34_append_only()',t||'_immutable',t); END LOOP; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['tracking_vehicle_states','tracking_trip_progress','tracking_eta_assessments','tracking_route_deviations','tracking_geofences','tracking_geofence_events','tracking_replay_sessions','tracking_alerts','tracking_alert_acknowledgements','tracking_customer_visibility_policies','tracking_hourly_checks','tracking_customer_updates','tracking_map_provider_configs','tracking_map_match_records','tracking_data_quality_events','tracking_operational_settings','tracking_audit_logs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('GRANT SELECT,INSERT ON public.%I TO authenticated',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING(public.tracking34_internal_read(company_id))',t||'_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK(public.tracking34_internal_write(company_id))',t||'_insert',t); END LOOP; END $$;
GRANT UPDATE ON public.tracking_trip_progress,public.tracking_geofences,public.tracking_alerts,public.tracking_customer_visibility_policies,public.tracking_hourly_checks,public.tracking_customer_updates,public.tracking_map_provider_configs,public.tracking_operational_settings TO authenticated;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['tracking_trip_progress','tracking_geofences','tracking_alerts','tracking_customer_visibility_policies','tracking_hourly_checks','tracking_customer_updates','tracking_map_provider_configs','tracking_operational_settings'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING(public.tracking34_internal_write(company_id)) WITH CHECK(public.tracking34_internal_write(company_id))',t||'_update',t); END LOOP; END $$;
CREATE POLICY tracking_visibility_customer_read ON public.tracking_customer_visibility_policies FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.customer_portal_memberships m WHERE m.company_id=tracking_customer_visibility_policies.company_id AND m.customer_id=tracking_customer_visibility_policies.customer_id AND m.user_id=auth.uid() AND m.status='active'));
CREATE POLICY tracking_updates_customer_read ON public.tracking_customer_updates FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.customer_portal_memberships m WHERE m.company_id=tracking_customer_updates.company_id AND m.customer_id=tracking_customer_updates.customer_id AND m.user_id=auth.uid() AND m.status='active'));
CREATE INDEX tracking_vehicle_states_current_idx ON public.tracking_vehicle_states(company_id,vehicle_id,calculated_at DESC);
CREATE INDEX tracking_alerts_active_idx ON public.tracking_alerts(company_id,status,priority,created_at DESC);
CREATE INDEX tracking_hourly_checks_due_idx ON public.tracking_hourly_checks(company_id,checked_at DESC,follow_up_due_at);
COMMENT ON FUNCTION public.tracking34_customer_locations IS 'Server-enforced customer location mode and delay; raw telemetry remains inaccessible to customer portal users.';
COMMENT ON TABLE public.tracking_map_match_records IS 'Matched coordinates supplement and never replace immutable raw telemetry.';
